#!/usr/bin/env node
// Render a captured conversation JSONL into a compact readable digest.
import { createInterface } from 'node:readline';

const MAXTEXT = Number(process.env.MAXTEXT || 1400);
const clip = (s, n = MAXTEXT) => {
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = s.replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + ` …[+${s.length - n}ch]` : s;
};

const rl = createInterface({ input: process.stdin, crlfDelay: Infinity });
let first = null, last = null, n = 0;
const lines = [];
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  n++;
  const ts = e.timestamp || '';
  if (!first) first = ts; last = ts;
  const t = ts ? ts.slice(11, 19) : '--------';
  const usage = e.message?.usage;
  const utok = usage ? ` [in:${(usage.input_tokens||0)+(usage.cache_read_input_tokens||0)+(usage.cache_creation_input_tokens||0)} out:${usage.output_tokens||0}]` : '';
  if (e.type === 'user') {
    const c = e.message?.content;
    if (typeof c === 'string') { lines.push(`${t} USER: ${clip(c, 2500)}`); continue; }
    for (const b of c || []) {
      if (b.type === 'text') lines.push(`${t} USER: ${clip(b.text, 2500)}`);
      else if (b.type === 'tool_result') {
        const body = typeof b.content === 'string' ? b.content : JSON.stringify(b.content);
        lines.push(`${t}   result${b.is_error ? ' ERROR' : ''}: ${clip(body, 220)}`);
      }
    }
  } else if (e.type === 'assistant') {
    for (const b of e.message?.content || []) {
      if (b.type === 'text') lines.push(`${t} ASSISTANT${utok}: ${clip(b.text)}`);
      else if (b.type === 'thinking') lines.push(`${t}  (thinking): ${clip(b.thinking, 600)}`);
      else if (b.type === 'tool_use') lines.push(`${t}   TOOL ${b.name}(${clip(b.input, 300)})`);
    }
  } else if (e.type === 'system') {
    lines.push(`${t} SYSTEM: ${clip(e.content || e.subtype || '', 300)}`);
  } else if (e.type === 'attachment') {
    // skip noise
  } else {
    lines.push(`${t} ${e.type}: ${clip(e.content || e.summary || '', 200)}`);
  }
}
console.log(`### entries=${n} first=${first} last=${last}`);
console.log(lines.join('\n'));

